from __future__ import annotations
import base64, hashlib, importlib.metadata, io, json, shutil, subprocess, sys, tarfile, time, traceback
from pathlib import Path, PurePosixPath
from zipfile import ZIP_DEFLATED, ZipFile, ZipInfo

RUNTIME_B64 = ""
RUNTIME_SHA256 = "4b3892a6d3e9226ed0f09f638f1817175c8c11e2d92d6fd27c3a1389db4e4ebb"
STAGE = "setup"

def safe_extract(payload, destination):
    with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as archive:
        members = archive.getmembers()
        if len(members) > 256 or sum(item.size for item in members) > 16 * 1024 * 1024:
            raise RuntimeError("runtime archive exceeds limit")
        for item in members:
            path = PurePosixPath(item.name)
            if item.isdir() or item.issym() or item.islnk() or path.is_absolute() or ".." in path.parts:
                raise RuntimeError("unsafe runtime member")
        archive.extractall(destination, filter="data")

def materialize_resume(source, destination):
    if source is None or source.is_file():
        return source
    with ZipFile(destination, "w") as archive:
        for path in sorted(source.rglob("*")):
            if not path.is_file():
                continue
            name = path.relative_to(source).as_posix()
            info = ZipInfo(name, (2026, 1, 1, 0, 0, 0))
            info.compress_type = ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes())
    return destination

try:
    RUN_ROOT = Path("/kaggle/working/tree_hetero_runs") / str(time.time_ns())
    RUNTIME_ROOT = RUN_ROOT / "runtime"
    RUNTIME_ROOT.mkdir(parents=True)
    runtime = base64.b64decode(RUNTIME_B64, validate=True)
    if hashlib.sha256(runtime).hexdigest() != RUNTIME_SHA256:
        raise RuntimeError("embedded runtime SHA-256 differs")
    safe_extract(runtime, RUNTIME_ROOT)
    sys.path.insert(0, str(RUNTIME_ROOT))
    print(f"TREE_HETERO_CODE_READY sha256={RUNTIME_SHA256} size_bytes={len(runtime)}", flush=True)

    STAGE = "dependencies"
    required = {"xgboost": "3.0.2", "lightgbm": "4.6.0"}
    missing = []
    for package, version in required.items():
        try:
            actual = importlib.metadata.version(package)
        except importlib.metadata.PackageNotFoundError:
            actual = "missing"
        if actual != version:
            missing.append(f"{package}=={version}")
    if missing:
        subprocess.check_call([sys.executable, "-m", "pip", "install", "-q", *missing])
    print("TREE_HETERO_DEPENDENCIES_READY " + " ".join(
        f"{name}={importlib.metadata.version(name)}" for name in sorted(required)
    ), flush=True)

    STAGE = "gpu"
    names = subprocess.check_output(
        ["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"], text=True,
    ).strip().splitlines()
    if len(names) != 2 or any("T4" not in name for name in names):
        raise RuntimeError(f"T4x2 required; found={names}")
    print(f"TREE_HETERO_GPU_READY count=2 names={' | '.join(names)}", flush=True)

    STAGE = "inputs"
    from experiments.tree_expert.hetero_kaggle import discover_hetero_inputs
    from experiments.tree_expert.hetero_runner import run_hetero_campaign
    from experiments.tree_expert.t3_inputs import verify_and_extract_t3_input, verify_official_data
    discovered = discover_hetero_inputs(Path("/kaggle/input"))
    official_roots = sorted({path.parent for path in Path("/kaggle/input").rglob("train.csv") if (path.parent / "trackman_history.csv").is_file()})
    if len(official_roots) != 1:
        raise RuntimeError(f"official data count must be one; found={len(official_roots)}")
    official = verify_official_data(official_roots[0])
    verified = verify_and_extract_t3_input(discovered.t3_input, RUN_ROOT / "verified_input")
    resume = materialize_resume(discovered.resume, RUN_ROOT / "uploaded_resume.zip")
    print(f"TREE_HETERO_INPUTS_VERIFIED input={discovered.t3_input} resume={resume}", flush=True)

    STAGE = "campaign"
    result = run_hetero_campaign(
        verified, official, RUN_ROOT / "campaign", resume_bundle=resume,
        wall_deadline=time.monotonic() + 28_200,
    )
    final = Path("/kaggle/working/tree_hetero_handoff.zip")
    shutil.copy2(result.handoff_bundle, final)
    print(f"TREE_HETERO_HANDOFF_READY path={final} status={result.status}", flush=True)
    print(f"TREE_HETERO_SUCCESS handoff={final} decisions={dict(result.decisions)}", flush=True)
except Exception as error:
    print(f"TREE_HETERO_ERROR stage={STAGE} type={type(error).__name__} message={str(error).replace(' ', '_')}", flush=True)
    traceback.print_exc()
    handoffs = sorted(Path("/kaggle/working/tree_hetero_runs").rglob("tree_hetero_handoff.zip"), key=lambda path: path.stat().st_mtime_ns)
    if handoffs:
        final = Path("/kaggle/working/tree_hetero_handoff.zip")
        shutil.copy2(handoffs[-1], final)
        print(f"TREE_HETERO_HANDOFF_READY path={final} status=emergency", flush=True)
